function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (request.method === 'GET' && url.pathname === '/') {
      sendHtml(response, 200, projectList('', projectFilter(url.searchParams.get('filter')), searchQuery(url.searchParams)));
      return;
    }
    if (request.method === 'POST' && url.pathname === '/projects') {
      const body = await readForm(request);
      const name = (body.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 400, projectList('Project name is required', projectFilter(body.get('filter')), searchQuery(body)));
        return;
      }
      createProject.run(name);
      redirect(response, projectListLocation(projectFilter(body.get('filter')), searchQuery(body)));
      return;
    }
    const rangeMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/due-range$/);
    if (request.method === 'POST' && rangeMatch) {
      const project = findProject.get(rangeMatch[1]);
      if (project) {
        const body = await readForm(request);
        const filter = taskFilter(body.get('filter'));
        const priority = priorityFilter(body.get('priorityFilter'));
        const from = (body.get('from') || '').trim();
        const through = (body.get('through') || '').trim();
        const error = !validDueDate(from) || !validDueDate(through)
          ? 'Due range must use valid YYYY-MM-DD dates'
          : from && through && from > through ? 'Due from must not be after Due through' : '';
        if (error) {
          sendHtml(response, 400, projectPage(project, filter, error, priority, dueRange(body)));
        } else {
          redirect(response, projectLocation(project.id, filter, priority, { from, through }, searchQuery(body)));
        }
        return;
      }
    }
    const defaultMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/default-priority$/);
    if (request.method === 'POST' && defaultMatch) {
      const project = findProject.get(defaultMatch[1]);
      if (project) {
        const body = await readForm(request);
        const filter = taskFilter(body.get('filter'));
        const selectedPriority = priorityFilter(body.get('priorityFilter'));
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filter, 'Archived project', selectedPriority, dueRange(body)));
          return;
        }
        const priority = body.get('priority');
        if (!['Low', 'Normal', 'High'].includes(priority)) {
          sendHtml(response, 400, projectPage(project, filter, 'Invalid task priority', selectedPriority, dueRange(body)));
          return;
        }
        setDefaultPriority.run(priority, project.id);
        redirect(response, projectLocation(project.id, filter, selectedPriority, dueRange(body)));
        return;
      }
    }
    const renameMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/rename$/);
    if (request.method === 'POST' && renameMatch) {
      const project = findProject.get(renameMatch[1]);
      if (project) {
        const body = await readForm(request);
        const filter = taskFilter(body.get('filter'));
        const priority = priorityFilter(body.get('priorityFilter'));
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filter, 'Archived project', priority, dueRange(body)));
          return;
        }
        const name = (body.get('name') || '').trim();
        if (!name) {
          sendHtml(response, 400, projectPage(project, filter, 'Project name is required', priority, dueRange(body)));
          return;
        }
        renameProject.run(name, project.id);
        redirect(response, projectLocation(project.id, filter, priority, dueRange(body)));
        return;
      }
    }
    const archiveMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/(archive|restore)$/);
    if (request.method === 'POST' && archiveMatch) {
      const body = await readForm(request);
      const result = archiveProject.run(archiveMatch[2] === 'archive' ? 1 : 0, archiveMatch[1]);
      if (result.changes) {
        redirect(response, projectListLocation(archiveMatch[2] === 'archive' ? 'Active' : 'Archived', searchQuery(body)));
        return;
      }
    }
    const match = url.pathname.match(/^\/projects\/([1-9]\d*)$/);
    if (request.method === 'GET' && match) {
      const project = findProject.get(match[1]);
      if (project) {
        sendHtml(response, 200, projectPage(project, taskFilter(url.searchParams.get('filter')), '', priorityFilter(url.searchParams.get('priorityFilter')), dueRange(url.searchParams), searchQuery(url.searchParams)));
        return;
      }
    }
    const taskMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*)\/(completion|rename|priority|due-date|move))?$/);
    if (request.method === 'POST' && taskMatch) {
      const project = findProject.get(taskMatch[1]);
      if (project) {
        const body = await readForm(request);
        const filter = taskFilter(body.get('filter'));
        const selectedPriority = priorityFilter(body.get('priorityFilter'));
        if (project.archived) {
          sendHtml(response, 403, projectPage(project, filter, 'Archived project', selectedPriority, dueRange(body)));
          return;
        }
        if (taskMatch[2]) {
          const title = (body.get('title') || '').trim();
          if (taskMatch[3] === 'rename' && !title) {
            sendHtml(response, 400, projectPage(project, filter, 'Task title is required', selectedPriority, dueRange(body)));
            return;
          }
          const priority = body.get('priority');
          if (taskMatch[3] === 'priority' && !['Low', 'Normal', 'High'].includes(priority)) {
            sendHtml(response, 400, projectPage(project, filter, 'Invalid task priority', selectedPriority, dueRange(body)));
            return;
          }
          const dueDate = (body.get('dueDate') || '').trim();
          if (taskMatch[3] === 'due-date' && !validDueDate(dueDate)) {
            sendHtml(response, 400, projectPage(project, filter, 'Due date must be a valid YYYY-MM-DD date', selectedPriority, dueRange(body)));
            return;
          }
          let result;
          if (taskMatch[3] === 'move') {
            const destinationId = body.get('destination') || '';
            const destination = /^[1-9]\d*$/.test(destinationId) ? findProject.get(destinationId) : null;
            if (!destination || destination.archived || destination.id === project.id) {
              sendHtml(response, 400, projectPage(project, filter, 'Choose an active destination project', selectedPriority, dueRange(body)));
              return;
            }
            result = transaction(() => {
              rememberDestination.run(destination.id, destination.id, taskMatch[2], project.id);
              return moveTask.run(destination.id, destination.id, taskMatch[2], project.id);
            });
          } else if (taskMatch[3] === 'due-date') {
            result = setTaskDueDate.run(dueDate, taskMatch[2], project.id);
          } else if (taskMatch[3] === 'rename') {
            result = renameTask.run(title, taskMatch[2], project.id);
          } else if (taskMatch[3] === 'priority') {
            result = setTaskPriority.run(priority, taskMatch[2], project.id);
          } else {
            result = completeTask.run(body.get('completed') === '1' ? 1 : 0, taskMatch[2], project.id);
          }
          if (!result.changes) {
            sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
            return;
          }
        } else {
          const title = (body.get('title') || '').trim();
          if (!title) {
            sendHtml(response, 400, projectPage(project, filter, 'Task title is required', selectedPriority, dueRange(body)));
            return;
          }
          transaction(() => {
            const task = createTask.run(project.id, title, project.default_priority, project.id);
            rememberCreatedTask.run(task.lastInsertRowid);
          });
        }
        redirect(response, projectLocation(project.id, filter, selectedPriority, dueRange(body)));
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Not found</h1><a href="/">Projects</a>'));
  } catch (error) {
    console.error(error);
    if (!response.headersSent) {
      const status = error.status || 500;
      const title = status === 413 ? 'Request too large' : 'Server error';
      sendHtml(response, status, page(title, `<h1>${title}</h1>`));
    } else {
      response.end();
    }
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

test('search normalizes spaces and tabs only for matching, without rewriting persisted data', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-search-whitespace-'));
  let child;
  let base;
  const start = async () => {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'db.sqlite') },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    base = await new Promise((resolve, reject) => {
      child.stdout.on('data', data => {
        const match = String(data).match(/port (\d+)/);
        if (match) resolve(`http://127.0.0.1:${match[1]}`);
      });
      child.once('error', reject);
      child.once('exit', code => reject(new Error(`Exited ${code}`)));
    });
  };
  const stop = async () => {
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
    child = undefined;
  };
  const post = (path, values = {}) => fetch(base + path, {
    method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
  });
  const html = path => fetch(base + path).then(response => response.text());
  const projectIds = text => [...text.matchAll(/method="get" action="\/projects\/(\d+)"/g)].map(m => Number(m[1]));
  const taskIds = text => [...text.matchAll(/class="completion-form"[^>]*tasks\/(\d+)\/completion/g)].map(m => Number(m[1]));
  const projectName = 'MiXeD  \t \t Board';
  const taskTitle = 'MiXeD\t\t  Task';
  try {
    await start();
    for (const name of [projectName, 'mixed board', 'mixed\nboard', 'mixed\u00a0board']) await post('/projects', { name });
    for (const title of [taskTitle, 'mixed task', 'mixed\ntask', 'mixed\u00a0task']) await post('/projects/1/tasks', { title });
    for (const query of ['mixed board', '  MIXED\t \tBOARD  ', 'xed\t bo']) {
      assert.deepEqual(projectIds(await html('/?' + new URLSearchParams({ search: query }))), [1, 2]);
    }
    for (const query of ['mixed task', '\t MIXED  \t TASK \t', 'xed\t ta']) {
      assert.deepEqual(taskIds(await html('/projects/1?' + new URLSearchParams({ search: query }))), [1, 2]);
    }
    await post('/projects/1/tasks/1/completion', { completed: '1' });
    assert.deepEqual(taskIds(await html('/projects/1?search=mixed%20task&filter=Completed')), [1]);
    await post('/projects/1/tasks/1/rename', { title: 'Renamed \t  Task', search: 'renamed task' });
    assert.deepEqual(taskIds(await html('/projects/1?search=renamed%20task')), [1]);
    await post('/projects/1/tasks/1/rename', { title: taskTitle });
    await post('/projects/1/archive');
    assert.deepEqual(projectIds(await html('/?search=mixed%20board')), [2]);
    assert.deepEqual(projectIds(await html('/?filter=Archived&search=MIXED%09%20BOARD')), [1]);
    assert.deepEqual(taskIds(await html('/projects/1?search=mixed%20task')), [1, 2]);
    await stop();
    await start();
    const list = await html('/?filter=Archived&search=mixed%20board');
    assert.deepEqual(projectIds(list), [1]);
    assert.ok(list.includes(projectName));
    const tasks = await html('/projects/1?search=mixed%20task');
    assert.deepEqual(taskIds(tasks), [1, 2]);
    assert.ok(tasks.includes(taskTitle));
    assert.ok((await html('/projects/1')).includes(taskTitle));
    await post('/projects/1/restore');
    assert.ok((await html('/')).includes(projectName));
  } finally {
    if (child) await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

